window.CODE = Object.assign(window.CODE || {}, {"ch07/rag.py":"\"\"\"Retrieval-augmented generation (RAG) over City Clinic policy documents.\n\nPipeline:  load -> split into sections -> embed -> store -> retrieve -> generate with citations\nRun:  pip install chromadb\n      python rag.py \"What are ICU visiting hours?\"\n\"\"\"\nimport re\nimport sys\nfrom pathlib import Path\n\nimport chromadb\n\nsys.path.insert(0, str(Path(__file__).resolve().parent.parent))\nfrom llm import chat, embed  # noqa: E402\n\nDOCS = Path(__file__).with_name(\"docs\")\nMIN_SIMILARITY = 0.30          # below this, a chunk is treated as \"not relevant\"\n\nSYSTEM = \"\"\"You are the City Clinic helpdesk. Answer ONLY from the numbered sources below.\n- After each fact, cite its source number like [1].\n- If the sources do not contain the answer, say exactly: \"I don't have that information. Please ask the front desk.\"\n- Never give medical advice. Keep the answer short.\"\"\"\n\n\n# ---------- 1. LOAD and SPLIT: one chunk per \"## \" section, keeping the document and section titles\ndef load_chunks() -> list[dict]:\n    chunks = []\n    for path in sorted(DOCS.glob(\"*.md\")):\n        text = path.read_text(encoding=\"utf-8\")\n        title = text.splitlines()[0].lstrip(\"# \").strip()\n        version = re.search(r\"Version \\d+, effective [^.\\n]+\", text)\n        for section in re.split(r\"\\n(?=## )\", text)[1:]:\n            heading, _, body = section.partition(\"\\n\")\n            heading = heading.lstrip(\"# \").strip()\n            chunks.append({\n                \"id\": f\"{path.stem}#{heading.lower().replace(' ', '-')}\",\n                # The heading goes into the text we embed: it tells the model what the chunk is about.\n                \"text\": f\"{title} - {heading}\\n{body.strip()}\",\n                \"meta\": {\"source\": path.name, \"title\": title, \"section\": heading,\n                         \"version\": version.group(0) if version else \"\"},\n            })\n    return chunks\n\n\n# ---------- 2. EMBED and STORE\ndef build_index(chunks: list[dict]):\n    client = chromadb.EphemeralClient()          # in memory; use PersistentClient in production\n    col = client.get_or_create_collection(\"clinic_policies\", embedding_function=None,\n                                          metadata={\"hnsw:space\": \"cosine\"})\n    col.upsert(ids=[c[\"id\"] for c in chunks], documents=[c[\"text\"] for c in chunks],\n               metadatas=[c[\"meta\"] for c in chunks], embeddings=embed([c[\"text\"] for c in chunks]))\n    return col\n\n\n# ---------- 3. RETRIEVE\ndef retrieve(col, question: str, k: int = 4) -> list[dict]:\n    r = col.query(query_embeddings=embed([question]), n_results=k)\n    hits = [{\"id\": i, \"text\": d, \"meta\": m, \"similarity\": round(1 - dist, 3)}\n            for i, d, m, dist in zip(r[\"ids\"][0], r[\"documents\"][0], r[\"metadatas\"][0], r[\"distances\"][0])]\n    return [h for h in hits if h[\"similarity\"] >= MIN_SIMILARITY]   # drop weak matches\n\n\n# ---------- 4. GENERATE with numbered sources\ndef answer(col, question: str) -> dict:\n    hits = retrieve(col, question)\n    if not hits:                                  # nothing relevant: do not let the model guess\n        return {\"answer\": \"I don't have that information. Please ask the front desk.\", \"sources\": []}\n    context = \"\\n\\n\".join(f\"[{n}] ({h['meta']['title']} - {h['meta']['section']}, {h['meta']['version']})\\n{h['text']}\"\n                          for n, h in enumerate(hits, 1))\n    reply = chat(f\"Sources:\\n{context}\\n\\nQuestion: {question}\", system=SYSTEM, temperature=0, max_tokens=300)\n    return {\"answer\": reply[\"text\"], \"sources\": hits}\n\n\nif __name__ == \"__main__\":\n    collection = build_index(load_chunks())\n    q = \" \".join(sys.argv[1:]) or \"Can my 10-year-old son visit his grandfather in the ICU?\"\n    result = answer(collection, q)\n    print(result[\"answer\"])\n    print(\"\\nSources:\")\n    for n, h in enumerate(result[\"sources\"], 1):\n        print(f\"  [{n}] {h['meta']['source']} > {h['meta']['section']}  (similarity {h['similarity']})\")\n","ch07/rag_eval.json":"[\n  {\"question\": \"What are the ICU visiting times?\", \"source\": \"visitors.md\", \"must_mention\": [\"11\"], \"answerable\": true},\n  {\"question\": \"Can a 10-year-old visit the ICU?\", \"source\": \"visitors.md\", \"must_mention_any\": [\"12\", \"not\"], \"answerable\": true},\n  {\"question\": \"Is OPD open on Sunday?\", \"source\": \"opd.md\", \"must_mention_any\": [\"closed\", \"no\"], \"answerable\": true},\n  {\"question\": \"How much is the OPD registration fee?\", \"source\": \"opd.md\", \"must_mention\": [\"100\"], \"answerable\": true},\n  {\"question\": \"Is a follow-up after 5 days charged?\", \"source\": \"opd.md\", \"must_mention_any\": [\"free\", \"no charge\"], \"answerable\": true},\n  {\"question\": \"Do you accept Ayushman Bharat?\", \"source\": \"insurance.md\", \"must_mention_any\": [\"yes\", \"accept\"], \"answerable\": true},\n  {\"question\": \"How early do I need pre-authorisation for a planned surgery?\", \"source\": \"insurance.md\", \"must_mention\": [\"48\"], \"answerable\": true},\n  {\"question\": \"Does PM-JAY pay for gloves and syringes?\", \"source\": \"insurance.md\", \"must_mention_any\": [\"not covered\", \"no\"], \"answerable\": true},\n  {\"question\": \"My father has chest pain, what should we do?\", \"source\": \"emergency.md\", \"must_mention_any\": [\"108\", \"emergency\"], \"answerable\": true},\n  {\"question\": \"What is the cafeteria menu today?\", \"source\": null, \"answerable\": false},\n  {\"question\": \"Who is the hospital's CEO?\", \"source\": null, \"answerable\": false}\n]\n","ch07/rag_eval.py":"\"\"\"Evaluate the RAG pipeline: is the right source found, is the answer correct, cited and faithful?\n\nFive checks per question:\n  retrieval     the expected source document is among the retrieved chunks\n  facts         the answer contains the key facts\n  citations     every [n] in the answer points to a real source (and there is at least one)\n  faithful      an LLM judge confirms every claim is supported by the sources\n  refusal       for questions the documents cannot answer, it says \"I don't have that information\"\n\nRun:  python rag_eval.py\n\"\"\"\nimport json\nimport re\nfrom pathlib import Path\n\nfrom rag import answer, build_index, chat, load_chunks\n\nCASES = json.loads(Path(__file__).with_name(\"rag_eval.json\").read_text())\nREFUSAL = \"i don't have that information\"\n\n\ndef faithful(ans: str, sources: list[dict]) -> bool:\n    ctx = \"\\n\\n\".join(f\"[{n}] {s['text']}\" for n, s in enumerate(sources, 1))\n    verdict = chat(f\"Sources:\\n{ctx}\\n\\nAnswer:\\n{ans}\\n\\nIs every factual claim in the answer supported by the sources? \"\n                   \"Reply YES or NO on the first line, then one short reason.\", temperature=0, max_tokens=60)[\"text\"]\n    return verdict.strip().upper().startswith(\"YES\")\n\n\ndef check(col, case: dict) -> dict:\n    r = answer(col, case[\"question\"])\n    text = r[\"answer\"].lower()\n    if not case[\"answerable\"]:\n        ok = REFUSAL in text\n        return {\"q\": case[\"question\"], \"retrieval\": None, \"facts\": None, \"citations\": None, \"faithful\": None,\n                \"refusal\": ok, \"passed\": ok}\n    found = any(s[\"meta\"][\"source\"] == case[\"source\"] for s in r[\"sources\"])\n    facts = (all(f.lower() in text for f in case.get(\"must_mention\", []))\n             and (not case.get(\"must_mention_any\") or any(f.lower() in text for f in case[\"must_mention_any\"])))\n    cited = [int(n) for n in re.findall(r\"\\[(\\d+)\\]\", r[\"answer\"])]\n    citations = bool(cited) and all(1 <= n <= len(r[\"sources\"]) for n in cited)\n    faith = faithful(r[\"answer\"], r[\"sources\"]) if r[\"sources\"] else False\n    return {\"q\": case[\"question\"], \"retrieval\": found, \"facts\": facts, \"citations\": citations,\n            \"faithful\": faith, \"refusal\": REFUSAL not in text, \"passed\": found and facts and citations and faith}\n\n\nif __name__ == \"__main__\":\n    col = build_index(load_chunks())\n    rows = [check(col, c) for c in CASES]\n    mark = lambda v: \"-\" if v is None else (\"✓\" if v else \"✗\")\n    print(f\"{'question':<58} ret fac cit fai ref\")\n    for r in rows:\n        print(f\"{r['q'][:56]:<58} {mark(r['retrieval']):^3} {mark(r['facts']):^3} {mark(r['citations']):^3} \"\n              f\"{mark(r['faithful']):^3} {mark(r['refusal']):^3}\")\n    answerable = [r for r in rows if r[\"retrieval\"] is not None]\n    print(f\"\\nPassed {sum(r['passed'] for r in rows)}/{len(rows)}  ·  retrieval hit rate \"\n          f\"{sum(r['retrieval'] for r in answerable) / len(answerable):.0%}  ·  faithfulness \"\n          f\"{sum(r['faithful'] for r in answerable) / len(answerable):.0%}\")\n","ch07/retrievers.py":"\"\"\"Better retrievers: multi-query and contextual compression.\n\nmulti_query   The model rewrites the question several ways, we search with each, and merge.\n              Helps when patients phrase things very differently from the documents.\ncompress      The model keeps only the sentences of each chunk that answer the question.\n              Smaller, cleaner context for the final answer.\n\nRun:  python retrievers.py\n\"\"\"\nimport json\n\nfrom rag import MIN_SIMILARITY, build_index, chat, embed, load_chunks\n\n\ndef multi_query(col, question: str, k: int = 3, n_rewrites: int = 3) -> list[dict]:\n    reply = chat(f\"Rewrite this hospital helpdesk question in {n_rewrites} different ways, using the words \"\n                 f\"a hospital policy document would use. Reply with a JSON list of strings only.\\n\\n{question}\",\n                 temperature=0.3, max_tokens=200)[\"text\"]\n    try:\n        rewrites = json.loads(reply.strip().removeprefix(\"```json\").removesuffix(\"```\"))\n    except json.JSONDecodeError:\n        rewrites = []                                      # fall back to the original question only\n    queries = [question] + [q for q in rewrites if isinstance(q, str)][:n_rewrites]\n    r = col.query(query_embeddings=embed(queries), n_results=k)\n    # Merge with Reciprocal Rank Fusion (Chapter 6): chunks found by several rewrites rise.\n    score, info = {}, {}\n    for ids, docs, metas, dists in zip(r[\"ids\"], r[\"documents\"], r[\"metadatas\"], r[\"distances\"]):\n        for rank, (i, d, m, dist) in enumerate(zip(ids, docs, metas, dists)):\n            if 1 - dist < MIN_SIMILARITY:\n                continue\n            score[i] = score.get(i, 0) + 1 / (60 + rank + 1)\n            info[i] = {\"id\": i, \"text\": d, \"meta\": m, \"similarity\": round(1 - dist, 3)}\n    return [info[i] for i in sorted(score, key=score.get, reverse=True)[:k]], queries\n\n\ndef compress(question: str, hits: list[dict]) -> list[dict]:\n    out = []\n    for h in hits:\n        kept = chat(f\"Question: {question}\\n\\nText:\\n{h['text']}\\n\\nCopy only the sentences from the text that help \"\n                    f\"answer the question, word for word. If none help, reply NONE.\", temperature=0, max_tokens=200)[\"text\"]\n        if kept.strip().upper() != \"NONE\":\n            out.append({**h, \"text\": kept.strip()})\n    return out\n\n\nif __name__ == \"__main__\":\n    col = build_index(load_chunks())\n    q = \"my wife is pregnant, when can I come and see her?\"\n    hits, queries = multi_query(col, q)\n    print(\"Searched with:\", *queries, sep=\"\\n  - \")\n    print(\"\\nFound:\", [h[\"id\"] for h in hits])\n    for h in compress(q, hits):\n        print(f\"\\n[{h['id']}] {h['text']}\")\n","common/llm.py":"\"\"\"One small helper so every chapter can call OpenAI or Anthropic the same way.\n\nChoose the provider in .env:   PROVIDER=openai   or   PROVIDER=anthropic\nOverride models if you like:   OPENAI_MODEL=...  ANTHROPIC_MODEL=...\n\n    from llm import chat, stream, achat\n    reply = chat(\"What are OPD timings?\", system=\"You are the City Clinic helpdesk.\")\n    print(reply[\"text\"], reply[\"input_tokens\"], reply[\"output_tokens\"])\n\"\"\"\nimport os\n\nfrom dotenv import load_dotenv\n\nload_dotenv()\nPROVIDER = os.getenv(\"PROVIDER\", \"openai\")\nMODELS = {\"openai\": os.getenv(\"OPENAI_MODEL\", \"gpt-4.1-mini\"),\n          \"anthropic\": os.getenv(\"ANTHROPIC_MODEL\", \"claude-haiku-5-5\")}\nTIMEOUT = float(os.getenv(\"LLM_TIMEOUT\", \"30\"))   # seconds per request; the SDK default is minutes\nRETRIES = int(os.getenv(\"LLM_RETRIES\", \"2\"))       # the SDKs retry rate limits and server errors for you\n_clients = {}\n\n\ndef _client(provider: str, use_async: bool = False):\n    key = (provider, use_async)\n    if key not in _clients:\n        if provider == \"openai\":\n            import openai\n            cls = openai.AsyncOpenAI if use_async else openai.OpenAI\n            _clients[key] = cls(timeout=TIMEOUT, max_retries=RETRIES)\n        else:\n            import anthropic\n            cls = anthropic.AsyncAnthropic if use_async else anthropic.Anthropic\n            _clients[key] = cls(timeout=TIMEOUT, max_retries=RETRIES)\n    return _clients[key]\n\n\ndef _openai_messages(user, system, history):\n    msgs = [{\"role\": \"system\", \"content\": system}] if system else []\n    return msgs + list(history or []) + [{\"role\": \"user\", \"content\": user}]\n\n\ndef _anthropic_args(user, system, history, temperature, max_tokens, model):\n    args = {\"model\": model, \"max_tokens\": max_tokens,\n            \"messages\": list(history or []) + [{\"role\": \"user\", \"content\": user}]}\n    if system:\n        args[\"system\"] = system\n    # `temperature` is accepted so both providers share one call shape, but it is NOT sent to Anthropic: the\n    # current anthropic SDK (1.x and later) raises TypeError if you pass it. OpenAI still honours it.\n    return args\n\n\ndef chat(user: str, system: str | None = None, history: list | None = None,\n         temperature: float | None = None, max_tokens: int = 800, provider: str | None = None) -> dict:\n    \"\"\"Send one message (plus optional earlier history). Returns text and token counts.\"\"\"\n    provider = provider or PROVIDER\n    model = MODELS[provider]\n    if provider == \"openai\":\n        kwargs = {\"model\": model, \"messages\": _openai_messages(user, system, history), \"max_completion_tokens\": max_tokens}\n        if temperature is not None:\n            kwargs[\"temperature\"] = temperature\n        r = _client(provider).chat.completions.create(**kwargs)\n        return {\"text\": r.choices[0].message.content, \"input_tokens\": r.usage.prompt_tokens,\n                \"output_tokens\": r.usage.completion_tokens, \"model\": model}\n    r = _client(provider).messages.create(**_anthropic_args(user, system, history, temperature, max_tokens, model))\n    return {\"text\": \"\".join(b.text for b in r.content if b.type == \"text\"), \"input_tokens\": r.usage.input_tokens,\n            \"output_tokens\": r.usage.output_tokens, \"model\": model}\n\n\ndef stream(user: str, system: str | None = None, history: list | None = None,\n           max_tokens: int = 800, provider: str | None = None):\n    \"\"\"Yield the reply a few words at a time, as the model writes it.\"\"\"\n    provider = provider or PROVIDER\n    model = MODELS[provider]\n    if provider == \"openai\":\n        chunks = _client(provider).chat.completions.create(\n            model=model, messages=_openai_messages(user, system, history), max_completion_tokens=max_tokens, stream=True)\n        for chunk in chunks:\n            if chunk.choices and chunk.choices[0].delta.content:\n                yield chunk.choices[0].delta.content\n    else:\n        with _client(provider).messages.stream(**_anthropic_args(user, system, history, None, max_tokens, model)) as s:\n            yield from s.text_stream\n\n\nasync def achat(user: str, system: str | None = None, temperature: float | None = None,\n                max_tokens: int = 800, provider: str | None = None) -> dict:\n    \"\"\"Async version of chat(), for running many calls at the same time (Chapter 4).\"\"\"\n    provider = provider or PROVIDER\n    model = MODELS[provider]\n    if provider == \"openai\":\n        kwargs = {\"model\": model, \"messages\": _openai_messages(user, system, None), \"max_completion_tokens\": max_tokens}\n        if temperature is not None:\n            kwargs[\"temperature\"] = temperature\n        r = await _client(provider, use_async=True).chat.completions.create(**kwargs)\n        return {\"text\": r.choices[0].message.content, \"input_tokens\": r.usage.prompt_tokens,\n                \"output_tokens\": r.usage.completion_tokens, \"model\": model}\n    r = await _client(provider, use_async=True).messages.create(\n        **_anthropic_args(user, system, None, temperature, max_tokens, model))\n    return {\"text\": \"\".join(b.text for b in r.content if b.type == \"text\"), \"input_tokens\": r.usage.input_tokens,\n            \"output_tokens\": r.usage.output_tokens, \"model\": model}\n\n\n# ---------------------------------------------------------------- embeddings (Chapter 6 onwards)\n# Anthropic does not offer its own embedding model, so embeddings come from OpenAI or from a\n# free local model. Choose in .env:  EMBEDDINGS=openai  (default)  or  EMBEDDINGS=local\nEMBEDDINGS = os.getenv(\"EMBEDDINGS\", \"openai\")\nEMBED_MODELS = {\"openai\": os.getenv(\"OPENAI_EMBED_MODEL\", \"text-embedding-3-small\"),\n                \"local\": os.getenv(\"LOCAL_EMBED_MODEL\", \"all-MiniLM-L6-v2\")}\n\n\ndef embed(texts: list[str], kind: str | None = None) -> list[list[float]]:\n    \"\"\"Turn each text into a vector of numbers that represents its meaning.\"\"\"\n    kind = kind or EMBEDDINGS\n    if kind == \"openai\":\n        r = _client(\"openai\").embeddings.create(model=EMBED_MODELS[\"openai\"], input=texts)\n        return [d.embedding for d in r.data]\n    if \"local\" not in _clients:                     # pip install sentence-transformers (downloads ~90 MB once)\n        from sentence_transformers import SentenceTransformer\n        _clients[\"local\"] = SentenceTransformer(EMBED_MODELS[\"local\"])\n    return _clients[\"local\"].encode(texts, normalize_embeddings=True).tolist()\n","common/requirements.txt":"# Pinned versions the course code was tested with. Install with: pip install -r requirements.txt\nopenai==3.43.0\nanthropic==2.4.0\npython-dotenv>=1.0\npydantic==2.13.5\ntiktoken>=0.8            # Chapter 2\nfastapi==0.162.0         # Chapter 5\nuvicorn>=0.30\npython-multipart>=0.0.9\nhttpx>=0.27\nstreamlit==1.66.1\ngradio==6.31.0\npytest>=8\n\n# Part C: frameworks and protocols (tested versions)\nlangchain==1.4.8                 # Chapters 12-13\nlangchain-core==1.7.4\nlangchain-openai==1.7.3\nlangchain-anthropic==1.7.9\nlangchain-community==0.4.2\nlangchain-text-splitters==1.1.3\nlangchain-classic==1.0.8         # only for legacy examples (AgentExecutor, old retrievers)\nlanggraph==1.2.19                # Chapters 14-15\nlanggraph-checkpoint-sqlite==3.1.3\nmcp==1.30.0                      # Chapters 16-17\nlangchain-mcp-adapters==0.3.2\nnetworkx==3.7                    # Chapter 18 (GraphRAG)\nchromadb==1.5.9                  # Chapters 6, 18, 19\nagno==3.1.12                     # Chapter 19\n# Optional: langchain-tavily, wikipedia, langchain-experimental (Chapter 13 built-in tools)\n# DSPy (Chapter 20) goes in a separate environment: see ch20/requirements-dspy.txt\n\n# Part D: multi-agent\n# CrewAI (Chapter 24) and AutoGen (Chapter 25) need their own environments: ch24/requirements-crewai.txt, ch25/requirements-autogen.txt\na2a-sdk==1.3.0                   # Chapter 26 (agent interoperability)\nfastapi==0.162.0\nuvicorn==0.54.0\n"});
